```javascript
import axios from 'axios';

const api = axios.create({
  baseURL: import.meta.env.VITE_API_URL || 'http://localhost:5000/api'
});

// Add token to requests
api.interceptors.request.use((config) => {
  const token = localStorage.getItem('token');
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

// Handle errors
api.interceptors.response.use(
  (response) => response,
  (error) => {
    if (error.response?.status === 401) {
      localStorage.removeItem('token');
      window.location.href = '/login';
    }
    return Promise.reject(error);
  }
);

export default api;
```

## Frontend - client/src/hooks/useItems.js

```javascript
import { useState, useEffect, useCallback } from 'react';
import api from '../services/api';

export function useItems() {
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [pagination, setPagination] = useState({
    page: 1,
    limit: 10,
    total: 0
  });

  const fetchItems = useCallback(async (params = {}) => {
    try {
      setLoading(true);
      const { data } = await api.get('/items', { params });
      setItems(data.data);
      setPagination(data.pagination);
    } catch (err) {
      setError(err.response?.data?.message || 'Error fetching items');
    } finally {
      setLoading(false);
    }
  }, []);

  const createItem = async (itemData) => {
    const { data } = await api.post('/items', itemData);
    setItems(prev => [data.data, ...prev]);
    return data.data;
  };

  const updateItem = async (id, itemData) => {
    const { data } = await api.put(`/items/${id}`, itemData);
    setItems(prev => prev.map(item =>
      item._id === id ? data.data : item
    ));
    return data.data;
  };

  const deleteItem = async (id) => {
    await api.delete(`/items/${id}`);
    setItems(prev => prev.filter(item => item._id !== id));
  };

  useEffect(() => {
    fetchItems();
  }, [fetchItems]);

  return {
    items,
    loading,
    error,
    pagination,
    fetchItems,
    createItem,
    updateItem,
    deleteItem
  };
}
```

## Frontend - client/src/context/AuthContext.jsx

```jsx
import { createContext, useState, useEffect } from 'react';
import api from '../services/api';

export const AuthContext = createContext();

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const token = localStorage.getItem('token');
    if (token) {
      loadUser();
    } else {
      setLoading(false);
    }
  }, []);

  const loadUser = async () => {
    try {
      const { data } = await api.get('/auth/me');
      setUser(data.data);
    } catch (error) {
      localStorage.removeItem('token');
    } finally {
      setLoading(false);
    }
  };

  const login = async (email, password) => {
    const { data } = await api.post('/auth/login', { email, password });
    localStorage.setItem('token', data.token);
    setUser(data.user);
    return data;
  };

  const register = async (name, email, password) => {
    const { data } = await api.post('/auth/register', { name, email, password });
    localStorage.setItem('token', data.token);
    setUser(data.user);
    return data;
  };

  const logout = () => {
    localStorage.removeItem('token');
    setUser(null);
  };

  return (
    <AuthContext.Provider value={{ user, loading, login, register, logout }}>
      {children}
    </AuthContext.Provider>
  );
}
```

## Frontend - client/src/components/ItemList.jsx

```jsx
import { useState } from 'react';
import { useItems } from '../hooks/useItems';
import ItemCard from './ItemCard';
import ItemForm from './ItemForm';

export default function ItemList() {
  const { items, loading, createItem, updateItem, deleteItem } = useItems();
  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState(null);

  const handleSubmit = async (data) => {
    if (editing) {
      await updateItem(editing._id, data);
    } else {
      await createItem(data);
    }
    setShowForm(false);
    setEditing(null);
  };

  if (loading) return <div className="text-center py-10">Loading...</div>;

  return (
    <div className="container mx-auto px-4 py-8">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold">My Items</h1>
        <button
          onClick={() => setShowForm(true)}
          className="bg-blue-500 text-white px-4 py-2 rounded hover:bg-blue-600"
        >
          Add Item
        </button>
      </div>

      {showForm && (
        <ItemForm
          item={editing}
          onSubmit={handleSubmit}
          onCancel={() => { setShowForm(false); setEditing(null); }}
        />
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {items.map(item => (
          <ItemCard
            key={item._id}
            item={item}
            onEdit={() => { setEditing(item); setShowForm(true); }}
            onDelete={() => deleteItem(item._id)}
          />
        ))}
      </div>
    </div>
  );
}
```

