package com.workoutapp.controller;

import com.workoutapp.dto.WorkoutDto;
import com.workoutapp.model.Workout;
import com.workoutapp.service.WorkoutService;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.web.bind.annotation.*;

import jakarta.validation.Valid;

@RestController
@RequestMapping("/api/workouts")
@RequiredArgsConstructor
public class WorkoutController {

    private final WorkoutService workoutService;

    @GetMapping
    public ResponseEntity<Page<Workout>> getAll(
            @AuthenticationPrincipal UserDetails userDetails,
            Pageable pageable,
            @RequestParam(required = false) String search
    ) {
        Page<Workout> workouts = workoutService.findAll(userDetails.getUsername(), search, pageable);
        return ResponseEntity.ok(workouts);
    }

    @GetMapping("/{id}")
    public ResponseEntity<Workout> getOne(
            @AuthenticationPrincipal UserDetails userDetails,
            @PathVariable Long id
    ) {
        Workout workout = workoutService.findById(id, userDetails.getUsername());
        return ResponseEntity.ok(workout);
    }

    @PostMapping
    public ResponseEntity<Workout> create(
            @AuthenticationPrincipal UserDetails userDetails,
            @Valid @RequestBody WorkoutDto dto
    ) {
        Workout workout = workoutService.create(dto, userDetails.getUsername());
        return ResponseEntity.status(HttpStatus.CREATED).body(workout);
    }

    @PutMapping("/{id}")
    public ResponseEntity<Workout> update(
            @AuthenticationPrincipal UserDetails userDetails,
            @PathVariable Long id,
            @Valid @RequestBody WorkoutDto dto
    ) {
        Workout workout = workoutService.update(id, dto, userDetails.getUsername());
        return ResponseEntity.ok(workout);
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<Void> delete(
            @AuthenticationPrincipal UserDetails userDetails,
            @PathVariable Long id
    ) {
        workoutService.delete(id, userDetails.getUsername());
        return ResponseEntity.noContent().build();
    }
}
