```java
package com.workoutapp.service;

import com.workoutapp.dto.WorkoutDto;
import com.workoutapp.exception.ResourceNotFoundException;
import com.workoutapp.model.Workout;
import com.workoutapp.model.User;
import com.workoutapp.repository.WorkoutRepository;
import com.workoutapp.repository.UserRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
public class WorkoutService {

    private final WorkoutRepository workoutRepository;
    private final UserRepository userRepository;

    public Page<Workout> findAll(String username, String search, Pageable pageable) {
        User user = getUserByUsername(username);
        if (search != null && !search.isEmpty()) {
            return workoutRepository.findByUserAndTitleContainingIgnoreCase(user, search, pageable);
        }
        return workoutRepository.findByUser(user, pageable);
    }

    public Workout findById(Long id, String username) {
        User user = getUserByUsername(username);
        return workoutRepository.findByIdAndUser(id, user)
                .orElseThrow(() -> new ResourceNotFoundException("Workout not found"));
    }

    @Transactional
    public Workout create(WorkoutDto dto, String username) {
        User user = getUserByUsername(username);
        Workout workout = new Workout();
        workout.setTitle(dto.getTitle());
        workout.setDescription(dto.getDescription());
        workout.setStatus(dto.getStatus() != null ? dto.getStatus() : "active");
        workout.setUser(user);
        return workoutRepository.save(workout);
    }

    @Transactional
    public Workout update(Long id, WorkoutDto dto, String username) {
        Workout workout = findById(id, username);
        if (dto.getTitle() != null) workout.setTitle(dto.getTitle());
        if (dto.getDescription() != null) workout.setDescription(dto.getDescription());
        if (dto.getStatus() != null) workout.setStatus(dto.getStatus());
        return workoutRepository.save(workout);
    }

    @Transactional
    public void delete(Long id, String username) {
        Workout workout = findById(id, username);
        workoutRepository.delete(workout);
    }

    private User getUserByUsername(String username) {
        return userRepository.findByEmail(username)
                .orElseThrow(() -> new ResourceNotFoundException("User not found"));
    }
}
