## Backend - JobService.java

```java
package com.jobapp.service;

import com.jobapp.dto.JobDto;
import com.jobapp.exception.ResourceNotFoundException;
import com.jobapp.model.Job;
import com.jobapp.model.User;
import com.jobapp.repository.JobRepository;
import com.jobapp.repository.UserRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
public class JobService {

    private final JobRepository jobRepository;
    private final UserRepository userRepository;

    public Page<Job> findAll(String username, String search, Pageable pageable) {
        User user = getUserByUsername(username);
        if (search != null && !search.isEmpty()) {
            return jobRepository.findByUserAndTitleContainingIgnoreCase(user, search, pageable);
        }
        return jobRepository.findByUser(user, pageable);
    }

    public Job findById(Long id, String username) {
        User user = getUserByUsername(username);
        return jobRepository.findByIdAndUser(id, user)
                .orElseThrow(() -> new ResourceNotFoundException("Job not found"));
    }

    @Transactional
    public Job create(JobDto dto, String username) {
        User user = getUserByUsername(username);
        Job job = new Job();
        job.setTitle(dto.getTitle());
        job.setDescription(dto.getDescription());
        job.setStatus(dto.getStatus() != null ? dto.getStatus() : "active");
        job.setUser(user);
        return jobRepository.save(job);
    }

    @Transactional
    public Job update(Long id, JobDto dto, String username) {
        Job job = findById(id, username);
        if (dto.getTitle() != null) job.setTitle(dto.getTitle());
        if (dto.getDescription() != null) job.setDescription(dto.getDescription());
        if (dto.getStatus() != null) job.setStatus(dto.getStatus());
        return jobRepository.save(job);
    }

    @Transactional
    public void delete(Long id, String username) {
        Job job = findById(id, username);
        jobRepository.delete(job);
    }

    private User getUserByUsername(String username) {
        return userRepository.findByEmail(username)
                .orElseThrow(() -> new ResourceNotFoundException("User not found"));
    }
}
