'use client';

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import RecipeForm from './RecipeForm';
import Card from './ui/Card';
import Button from './ui/Button';

interface Recipe {
  id: string;
  title: string;
  description: string | null;
  status: string;
  createdAt: Date;
}

export default function RecipeList({ initialRecipes }: { initialRecipes: Recipe[] }) {
  const [recipes, setRecipes] = useState(initialRecipes);
  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState<Recipe | null>(null);
  const router = useRouter();

  const handleCreate = async (data: any) => {
    const res = await fetch('/api/recipes', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data),
    });

    if (res.ok) {
      const { data: newRecipe } = await res.json();
      setRecipes([newRecipe, ...recipes]);
      setShowForm(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Are you sure?')) return;

    const res = await fetch(`/api/recipes/${id}`, { method: 'DELETE' });

    if (res.ok) {
      setRecipes(recipes.filter(item => item.id !== id));
    }
  };

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold">My Recipes</h1>
        <Button onClick={() => setShowForm(true)}>
          Add Recipe
        </Button>
      </div>

      {showForm && (
        <div className="mb-6">
          <RecipeForm
            onSubmit={handleCreate}
            onCancel={() => setShowForm(false)}
          />
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {recipes.map(recipe => (
          <Card key={recipe.id} className="p-4">
            <h3 className="font-semibold">{recipe.title}</h3>
            <p className="text-gray-600 text-sm">{recipe.description}</p>
            <div className="flex gap-2 mt-4">
              <Button size="sm" variant="outline" onClick={() => router.push(`/dashboard/recipes/${recipe.id}`)}>
                Edit
              </Button>
              <Button size="sm" variant="danger" onClick={() => handleDelete(recipe.id)}>
                Delete
              </Button>
            </div>
          </Card>
        ))}
      </div>
    </div>
  );
}
