'use client';

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import PropertyForm from './PropertyForm';
import Card from './ui/Card';
import Button from './ui/Button';

interface Property {
  id: string;
  title: string;
  description: string | null;
  status: string;
  createdAt: Date;
}

export default function PropertyList({ initialPropertys }: { initialPropertys: Property[] }) {
  const [properties, setPropertys] = useState(initialPropertys);
  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState<Property | null>(null);
  const router = useRouter();

  const handleCreate = async (data: any) => {
    const res = await fetch('/api/properties', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data),
    });

    if (res.ok) {
      const { data: newProperty } = await res.json();
      setPropertys([newProperty, ...properties]);
      setShowForm(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Are you sure?')) return;

    const res = await fetch(`/api/properties/${id}`, { method: 'DELETE' });

    if (res.ok) {
      setPropertys(properties.filter(item => item.id !== id));
    }
  };

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold">My Propertys</h1>
        <Button onClick={() => setShowForm(true)}>
          Add Property
        </Button>
      </div>

      {showForm && (
        <div className="mb-6">
          <PropertyForm
            onSubmit={handleCreate}
            onCancel={() => setShowForm(false)}
          />
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {properties.map(property => (
          <Card key={property.id} className="p-4">
            <h3 className="font-semibold">{property.title}</h3>
            <p className="text-gray-600 text-sm">{property.description}</p>
            <div className="flex gap-2 mt-4">
              <Button size="sm" variant="outline" onClick={() => router.push(`/dashboard/properties/${property.id}`)}>
                Edit
              </Button>
              <Button size="sm" variant="danger" onClick={() => handleDelete(property.id)}>
                Delete
              </Button>
            </div>
          </Card>
        ))}
      </div>
    </div>
  );
}
