export function useInvoices() {
  const [invoices, setInvoices] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [pagination, setPagination] = useState({
    page: 1,
    limit: 10,
    total: 0
  });

  const fetchInvoices = useCallback(async (params = {}) => {
    try {
      setLoading(true);
      const { data } = await api.get('/invoices', { params });
      setInvoices(data.data);
      setPagination(data.pagination);
    } catch (err) {
      setError(err.response?.data?.message || 'Error fetching invoices');
    } finally {
      setLoading(false);
    }
  }, []);

  const createInvoice = async (invoiceData) => {
    const { data } = await api.post('/invoices', invoiceData);
    setInvoices(prev => [data.data, ...prev]);
    return data.data;
  };

  const updateInvoice = async (id, invoiceData) => {
    const { data } = await api.put(`/invoices/${id}`, invoiceData);
    setInvoices(prev => prev.map(item =>
      item._id === id ? data.data : item
    ));
    return data.data;
  };

  const deleteInvoice = async (id) => {
    await api.delete(`/invoices/${id}`);
    setInvoices(prev => prev.filter(item => item._id !== id));
  };

  useEffect(() => {
    fetchInvoices();
  }, [fetchInvoices]);

  return {
    invoices,
    loading,
    error,
    pagination,
    fetchInvoices,
    createInvoice,
    updateInvoice,
    deleteInvoice
  };
}
