## Backend - UserService.java

```java
package com.userapp.service;

import com.userapp.dto.UserDto;
import com.userapp.exception.ResourceNotFoundException;
import com.userapp.model.User;
import com.userapp.model.User;
import com.userapp.repository.UserRepository;
import com.userapp.repository.UserRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
public class UserService {

    private final UserRepository userRepository;
    private final UserRepository userRepository;

    public Page<User> findAll(String username, String search, Pageable pageable) {
        User user = getUserByUsername(username);
        if (search != null && !search.isEmpty()) {
            return userRepository.findByUserAndTitleContainingIgnoreCase(user, search, pageable);
        }
        return userRepository.findByUser(user, pageable);
    }

    public User findById(Long id, String username) {
        User user = getUserByUsername(username);
        return userRepository.findByIdAndUser(id, user)
                .orElseThrow(() -> new ResourceNotFoundException("User not found"));
    }

    @Transactional
    public User create(UserDto dto, String username) {
        User user = getUserByUsername(username);
        User user = new User();
        user.setTitle(dto.getTitle());
        user.setDescription(dto.getDescription());
        user.setStatus(dto.getStatus() != null ? dto.getStatus() : "active");
        user.setUser(user);
        return userRepository.save(user);
    }

    @Transactional
    public User update(Long id, UserDto dto, String username) {
        User user = findById(id, username);
        if (dto.getTitle() != null) user.setTitle(dto.getTitle());
        if (dto.getDescription() != null) user.setDescription(dto.getDescription());
        if (dto.getStatus() != null) user.setStatus(dto.getStatus());
        return userRepository.save(user);
    }

    @Transactional
    public void delete(Long id, String username) {
        User user = findById(id, username);
        userRepository.delete(user);
    }

    private User getUserByUsername(String username) {
        return userRepository.findByEmail(username)
                .orElseThrow(() -> new ResourceNotFoundException("User not found"));
    }
}
