```javascript
import { useState, useEffect, useCallback } from 'react';
import api from '../services/api';

export function usePropertys() {
  const [properties, setPropertys] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [pagination, setPagination] = useState({
    page: 1,
    limit: 10,
    total: 0
  });

  const fetchPropertys = useCallback(async (params = {}) => {
    try {
      setLoading(true);
      const { data } = await api.get('/properties', { params });
      setPropertys(data.data);
      setPagination(data.pagination);
    } catch (err) {
      setError(err.response?.data?.message || 'Error fetching properties');
    } finally {
      setLoading(false);
    }
  }, []);

  const createProperty = async (propertyData) => {
    const { data } = await api.post('/properties', propertyData);
    setPropertys(prev => [data.data, ...prev]);
    return data.data;
  };

  const updateProperty = async (id, propertyData) => {
    const { data } = await api.put(`/properties/${id}`, propertyData);
    setPropertys(prev => prev.map(item =>
      item._id === id ? data.data : item
    ));
    return data.data;
  };

  const deleteProperty = async (id) => {
    await api.delete(`/properties/${id}`);
    setPropertys(prev => prev.filter(item => item._id !== id));
  };

  useEffect(() => {
    fetchPropertys();
  }, [fetchPropertys]);

  return {
    properties,
    loading,
    error,
    pagination,
    fetchPropertys,
    createProperty,
    updateProperty,
    deleteProperty
  };
}
