import { useState } from 'react';
import { usePropertys } from '../hooks/usePropertys';
import PropertyCard from './PropertyCard';
import PropertyForm from './PropertyForm';

export default function PropertyList() {
  const { properties, loading, createProperty, updateProperty, deleteProperty } = usePropertys();
  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState(null);

  const handleSubmit = async (data) => {
    if (editing) {
      await updateProperty(editing._id, data);
    } else {
      await createProperty(data);
    }
    setShowForm(false);
    setEditing(null);
  };

  if (loading) return <div className="text-center py-10">Loading...</div>;

  return (
    <div className="container mx-auto px-4 py-8">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold">My Propertys</h1>
        <button
          onClick={() => setShowForm(true)}
          className="bg-blue-500 text-white px-4 py-2 rounded hover:bg-blue-600"
        >
          Add Property
        </button>
      </div>

      {showForm && (
        <PropertyForm
          property={editing}
          onSubmit={handleSubmit}
          onCancel={() => { setShowForm(false); setEditing(null); }}
        />
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {properties.map(property => (
          <PropertyCard
            key={property._id}
            property={property}
            onEdit={() => { setEditing(property); setShowForm(true); }}
            onDelete={() => deleteProperty(property._id)}
          />
        ))}
      </div>
    </div>
  );
}
