package com.courseapp.controller;

import com.courseapp.dto.CourseDto;
import com.courseapp.model.Course;
import com.courseapp.service.CourseService;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.web.bind.annotation.*;

import jakarta.validation.Valid;

@RestController
@RequestMapping("/api/courses")
@RequiredArgsConstructor
public class CourseController {

    private final CourseService courseService;

    @GetMapping
    public ResponseEntity<Page<Course>> getAll(
            @AuthenticationPrincipal UserDetails userDetails,
            Pageable pageable,
            @RequestParam(required = false) String search
    ) {
        Page<Course> courses = courseService.findAll(userDetails.getUsername(), search, pageable);
        return ResponseEntity.ok(courses);
    }

    @GetMapping("/{id}")
    public ResponseEntity<Course> getOne(
            @AuthenticationPrincipal UserDetails userDetails,
            @PathVariable Long id
    ) {
        Course course = courseService.findById(id, userDetails.getUsername());
        return ResponseEntity.ok(course);
    }

    @PostMapping
    public ResponseEntity<Course> create(
            @AuthenticationPrincipal UserDetails userDetails,
            @Valid @RequestBody CourseDto dto
    ) {
        Course course = courseService.create(dto, userDetails.getUsername());
        return ResponseEntity.status(HttpStatus.CREATED).body(course);
    }

    @PutMapping("/{id}")
    public ResponseEntity<Course> update(
            @AuthenticationPrincipal UserDetails userDetails,
            @PathVariable Long id,
            @Valid @RequestBody CourseDto dto
    ) {
        Course course = courseService.update(id, dto, userDetails.getUsername());
        return ResponseEntity.ok(course);
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<Void> delete(
            @AuthenticationPrincipal UserDetails userDetails,
            @PathVariable Long id
    ) {
        courseService.delete(id, userDetails.getUsername());
        return ResponseEntity.noContent().build();
    }
}
