## Backend - CourseService.java

```java
package com.courseapp.service;

import com.courseapp.dto.CourseDto;
import com.courseapp.exception.ResourceNotFoundException;
import com.courseapp.model.Course;
import com.courseapp.model.User;
import com.courseapp.repository.CourseRepository;
import com.courseapp.repository.UserRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
public class CourseService {

    private final CourseRepository courseRepository;
    private final UserRepository userRepository;

    public Page<Course> findAll(String username, String search, Pageable pageable) {
        User user = getUserByUsername(username);
        if (search != null && !search.isEmpty()) {
            return courseRepository.findByUserAndTitleContainingIgnoreCase(user, search, pageable);
        }
        return courseRepository.findByUser(user, pageable);
    }

    public Course findById(Long id, String username) {
        User user = getUserByUsername(username);
        return courseRepository.findByIdAndUser(id, user)
                .orElseThrow(() -> new ResourceNotFoundException("Course not found"));
    }

    @Transactional
    public Course create(CourseDto dto, String username) {
        User user = getUserByUsername(username);
        Course course = new Course();
        course.setTitle(dto.getTitle());
        course.setDescription(dto.getDescription());
        course.setStatus(dto.getStatus() != null ? dto.getStatus() : "active");
        course.setUser(user);
        return courseRepository.save(course);
    }

    @Transactional
    public Course update(Long id, CourseDto dto, String username) {
        Course course = findById(id, username);
        if (dto.getTitle() != null) course.setTitle(dto.getTitle());
        if (dto.getDescription() != null) course.setDescription(dto.getDescription());
        if (dto.getStatus() != null) course.setStatus(dto.getStatus());
        return courseRepository.save(course);
    }

    @Transactional
    public void delete(Long id, String username) {
        Course course = findById(id, username);
        courseRepository.delete(course);
    }

    private User getUserByUsername(String username) {
        return userRepository.findByEmail(username)
                .orElseThrow(() -> new ResourceNotFoundException("User not found"));
    }
}
