  standalone: true,
  imports: [CommonModule, RouterLink, TaskCardComponent],
  template: `
    <div class="container mx-auto px-4 py-8">
      <div class="flex justify-between items-center mb-6">
        <h1 class="text-2xl font-bold">My Tasks</h1>
        <a routerLink="/tasks/new" class="bg-blue-500 text-white px-4 py-2 rounded">
          Add Task
        </a>
      </div>

      @if (loading()) {
        <div class="text-center py-10">Loading...</div>
      } @else {
        <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          @for (task of tasks(); track task.id) {
            <app-task-card
              [task]="task"
              (delete)="onDelete($event)"
            />
          }
        </div>
      }
    </div>
  `,
})
export class TaskListComponent implements OnInit {
  private taskService = inject(TaskService);

  tasks = signal<any[]>([]);
  loading = signal(true);

  ngOnInit() {
    this.loadTasks();
  }

  async loadTasks() {
    try {
      const response = await this.taskService.getAll();
      this.tasks.set(response.data);
    } finally {
      this.loading.set(false);
    }
  }

  async onDelete(id: string) {
    if (confirm('Are you sure?')) {
      await this.taskService.delete(id);
      this.tasks.update(tasks => tasks.filter(item => item.id !== id));
    }
  }
}
