import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository, Like } from 'typeorm';
import { Item } from './entities/item.entity';
import { CreateItemDto } from './dto/create-item.dto';
import { UpdateItemDto } from './dto/update-item.dto';

@Injectable()
export class ItemsService {
  constructor(
    @InjectRepository(Item)
    private itemsRepository: Repository<Item>,
  ) {}

  async findAll(userId: string, options: { page: number; limit: number; search?: string }) {
    const { page, limit, search } = options;

    const where: any = { userId };
    if (search) {
      where.title = Like(`%${search}%`);
    }

    const [data, total] = await this.itemsRepository.findAndCount({
      where,
      order: { createdAt: 'DESC' },
      skip: (page - 1) * limit,
      take: limit,
    });

    return {
      data,
      total,
      page,
      limit,
      pages: Math.ceil(total / limit),
    };
  }

  async findOne(id: string, userId: string) {
    const item = await this.itemsRepository.findOne({
      where: { id, userId },
    });

    if (!item) {
      throw new NotFoundException('Item not found');
    }

    return item;
  }

  async create(createItemDto: CreateItemDto, userId: string) {
    const item = this.itemsRepository.create({
      ...createItemDto,
      userId,
    });
    return this.itemsRepository.save(item);
  }

  async update(id: string, updateItemDto: UpdateItemDto, userId: string) {
    const item = await this.findOne(id, userId);
    Object.assign(item, updateItemDto);
    return this.itemsRepository.save(item);
  }

  async remove(id: string, userId: string) {
    const item = await this.findOne(id, userId);
    await this.itemsRepository.remove(item);
    return { deleted: true };
  }
}
