```typescript
import { defineStore } from 'pinia';
import { ref, computed } from 'vue';
import api from '@/services/api';

interface Item {
  id: string;
  title: string;
  description: string | null;
  status: string;
  createdAt: string;
}

export const useItemStore = defineStore('items', () => {
  const items = ref<Item[]>([]);
  const loading = ref(false);
  const error = ref<string | null>(null);
  const pagination = ref({ page: 1, limit: 10, total: 0 });

  const fetchItems = async (params?: Record<string, any>) => {
    loading.value = true;
    error.value = null;
    try {
      const { data } = await api.get('/items', { params });
      items.value = data.data;
      pagination.value = {
        page: data.page,
        limit: data.limit,
        total: data.total,
      };
    } catch (e: any) {
      error.value = e.response?.data?.detail || 'Error fetching items';
    } finally {
      loading.value = false;
    }
  };

  const createItem = async (data: Partial<Item>) => {
    const { data: newItem } = await api.post('/items', data);
    items.value.unshift(newItem);
    return newItem;
  };

  const updateItem = async (id: string, data: Partial<Item>) => {
    const { data: updated } = await api.put(`/items/${id}`, data);
    const index = items.value.findIndex(item => item.id === id);
    if (index !== -1) {
      items.value[index] = updated;
    }
    return updated;
  };

  const deleteItem = async (id: string) => {
    await api.delete(`/items/${id}`);
    items.value = items.value.filter(item => item.id !== id);
  };

  return {
    items,
    loading,
    error,
    pagination,
    fetchItems,
    createItem,
    updateItem,
    deleteItem,
  };
});
