## Backend - app/api/routes/recipes.py

```python
from fastapi import APIRouter, Depends, HTTPException, Query
from sqlalchemy.orm import Session
from typing import Optional
from app.api.deps import get_db, get_current_user
from app.models.recipe import Recipe
from app.models.user import User
from app.schemas.recipe import (
    RecipeCreate,
    RecipeUpdate,
    RecipeResponse,
    RecipeListResponse,
)

router = APIRouter()

@router.get("/", response_model=RecipeListResponse)
async def list_recipes(
    page: int = Query(1, ge=1),
    limit: int = Query(10, ge=1, le=100),
    search: Optional[str] = None,
    status: Optional[str] = None,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    query = db.query(Recipe).filter(Recipe.user_id == current_user.id)

    if search:
        query = query.filter(Recipe.title.ilike(f"%{search}%"))
    if status:
        query = query.filter(Recipe.status == status)

    total = query.count()
    recipes = query.offset((page - 1) * limit).limit(limit).all()

    return RecipeListResponse(
        data=recipes,
        total=total,
        page=page,
        limit=limit
    )

@router.get("/{id}", response_model=RecipeResponse)
async def get_recipe(
    id: str,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    recipe = db.query(Recipe).filter(
        Recipe.id == id,
        Recipe.user_id == current_user.id
    ).first()

    if not recipe:
        raise HTTPException(status_code=404, detail="Recipe not found")

    return recipe

@router.post("/", response_model=RecipeResponse, status_code=201)
async def create_recipe(
    data: RecipeCreate,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    recipe = Recipe(**data.model_dump(), user_id=current_user.id)
    db.add(recipe)
    db.commit()
    db.refresh(recipe)
    return recipe

@router.put("/{id}", response_model=RecipeResponse)
async def update_recipe(
    id: str,
    data: RecipeUpdate,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    recipe = db.query(Recipe).filter(
        Recipe.id == id,
        Recipe.user_id == current_user.id
    ).first()

    if not recipe:
        raise HTTPException(status_code=404, detail="Recipe not found")

    for key, value in data.model_dump(exclude_unset=True).items():
        setattr(recipe, key, value)

    db.commit()
    db.refresh(recipe)
    return recipe

@router.delete("/{id}", status_code=204)
async def delete_recipe(
    id: str,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    recipe = db.query(Recipe).filter(
        Recipe.id == id,
        Recipe.user_id == current_user.id
    ).first()

    if not recipe:
        raise HTTPException(status_code=404, detail="Recipe not found")

    db.delete(recipe)
    db.commit()
```

## Frontend - src/stores/recipes.ts

```typescript
import { defineStore } from 'pinia';
import { ref, computed } from 'vue';
import api from '@/services/api';

interface Recipe {
  id: string;
  title: string;
  description: string | null;
  status: string;
  createdAt: string;
}

export const useRecipeStore = defineStore('recipes', () => {
  const recipes = ref<Recipe[]>([]);
  const loading = ref(false);
  const error = ref<string | null>(null);
  const pagination = ref({ page: 1, limit: 10, total: 0 });

  const fetchRecipes = async (params?: Record<string, any>) => {
    loading.value = true;
    error.value = null;
    try {
      const { data } = await api.get('/recipes', { params });
      recipes.value = data.data;
      pagination.value = {
        page: data.page,
        limit: data.limit,
        total: data.total,
      };
    } catch (e: any) {
      error.value = e.response?.data?.detail || 'Error fetching recipes';
    } finally {
      loading.value = false;
    }
  };

  const createRecipe = async (data: Partial<Recipe>) => {
    const { data: newRecipe } = await api.post('/recipes', data);
    recipes.value.unshift(newRecipe);
    return newRecipe;
  };

  const updateRecipe = async (id: string, data: Partial<Recipe>) => {
    const { data: updated } = await api.put(`/recipes/${id}`, data);
    const index = recipes.value.findIndex(item => item.id === id);
    if (index !== -1) {
      recipes.value[index] = updated;
    }
    return updated;
  };

  const deleteRecipe = async (id: string) => {
    await api.delete(`/recipes/${id}`);
    recipes.value = recipes.value.filter(item => item.id !== id);
  };

  return {
    recipes,
    loading,
    error,
    pagination,
    fetchRecipes,
    createRecipe,
    updateRecipe,
    deleteRecipe,
  };
});
```

