'use client';

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import InvoiceForm from './InvoiceForm';
import Card from './ui/Card';
import Button from './ui/Button';

interface Invoice {
  id: string;
  title: string;
  description: string | null;
  status: string;
  createdAt: Date;
}

export default function InvoiceList({ initialInvoices }: { initialInvoices: Invoice[] }) {
  const [invoices, setInvoices] = useState(initialInvoices);
  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState<Invoice | null>(null);
  const router = useRouter();

  const handleCreate = async (data: any) => {
    const res = await fetch('/api/invoices', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data),
    });

    if (res.ok) {
      const { data: newInvoice } = await res.json();
      setInvoices([newInvoice, ...invoices]);
      setShowForm(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Are you sure?')) return;

    const res = await fetch(`/api/invoices/${id}`, { method: 'DELETE' });

    if (res.ok) {
      setInvoices(invoices.filter(item => item.id !== id));
    }
  };

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold">My Invoices</h1>
        <Button onClick={() => setShowForm(true)}>
          Add Invoice
        </Button>
      </div>

      {showForm && (
        <div className="mb-6">
          <InvoiceForm
            onSubmit={handleCreate}
            onCancel={() => setShowForm(false)}
          />
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {invoices.map(invoice => (
          <Card key={invoice.id} className="p-4">
            <h3 className="font-semibold">{invoice.title}</h3>
            <p className="text-gray-600 text-sm">{invoice.description}</p>
            <div className="flex gap-2 mt-4">
              <Button size="sm" variant="outline" onClick={() => router.push(`/dashboard/invoices/${invoice.id}`)}>
                Edit
              </Button>
              <Button size="sm" variant="danger" onClick={() => handleDelete(invoice.id)}>
                Delete
              </Button>
            </div>
          </Card>
        ))}
      </div>
    </div>
  );
}
