```typescript
import { defineStore } from 'pinia';
import { ref, computed } from 'vue';
import api from '@/services/api';

interface Ticket {
  id: string;
  title: string;
  description: string | null;
  status: string;
  createdAt: string;
}

export const useTicketStore = defineStore('tickets', () => {
  const tickets = ref<Ticket[]>([]);
  const loading = ref(false);
  const error = ref<string | null>(null);
  const pagination = ref({ page: 1, limit: 10, total: 0 });

  const fetchTickets = async (params?: Record<string, any>) => {
    loading.value = true;
    error.value = null;
    try {
      const { data } = await api.get('/tickets', { params });
      tickets.value = data.data;
      pagination.value = {
        page: data.page,
        limit: data.limit,
        total: data.total,
      };
    } catch (e: any) {
      error.value = e.response?.data?.detail || 'Error fetching tickets';
    } finally {
      loading.value = false;
    }
  };

  const createTicket = async (data: Partial<Ticket>) => {
    const { data: newTicket } = await api.post('/tickets', data);
    tickets.value.unshift(newTicket);
    return newTicket;
  };

  const updateTicket = async (id: string, data: Partial<Ticket>) => {
    const { data: updated } = await api.put(`/tickets/${id}`, data);
    const index = tickets.value.findIndex(item => item.id === id);
    if (index !== -1) {
      tickets.value[index] = updated;
    }
    return updated;
  };

  const deleteTicket = async (id: string) => {
    await api.delete(`/tickets/${id}`);
    tickets.value = tickets.value.filter(item => item.id !== id);
  };

  return {
    tickets,
    loading,
    error,
    pagination,
    fetchTickets,
    createTicket,
    updateTicket,
    deleteTicket,
  };
});
```

