## Frontend - src/stores/users.ts

```typescript
import { defineStore } from 'pinia';
import { ref, computed } from 'vue';
import api from '@/services/api';

interface User {
  id: string;
  title: string;
  description: string | null;
  status: string;
  createdAt: string;
}

export const useUserStore = defineStore('users', () => {
  const users = ref<User[]>([]);
  const loading = ref(false);
  const error = ref<string | null>(null);
  const pagination = ref({ page: 1, limit: 10, total: 0 });

  const fetchUsers = async (params?: Record<string, any>) => {
    loading.value = true;
    error.value = null;
    try {
      const { data } = await api.get('/users', { params });
      users.value = data.data;
      pagination.value = {
        page: data.page,
        limit: data.limit,
        total: data.total,
      };
    } catch (e: any) {
      error.value = e.response?.data?.detail || 'Error fetching users';
    } finally {
      loading.value = false;
    }
  };

  const createUser = async (data: Partial<User>) => {
    const { data: newUser } = await api.post('/users', data);
    users.value.unshift(newUser);
    return newUser;
  };

  const updateUser = async (id: string, data: Partial<User>) => {
    const { data: updated } = await api.put(`/users/${id}`, data);
    const index = users.value.findIndex(item => item.id === id);
    if (index !== -1) {
      users.value[index] = updated;
    }
    return updated;
  };

  const deleteUser = async (id: string) => {
    await api.delete(`/users/${id}`);
    users.value = users.value.filter(item => item.id !== id);
  };

  return {
    users,
    loading,
    error,
    pagination,
    fetchUsers,
    createUser,
    updateUser,
    deleteUser,
  };
});
```

