import { defineStore } from 'pinia';
import { ref, computed } from 'vue';
import api from '@/services/api';

interface Event {
  id: string;
  title: string;
  description: string | null;
  status: string;
  createdAt: string;
}

export const useEventStore = defineStore('events', () => {
  const events = ref<Event[]>([]);
  const loading = ref(false);
  const error = ref<string | null>(null);
  const pagination = ref({ page: 1, limit: 10, total: 0 });

  const fetchEvents = async (params?: Record<string, any>) => {
    loading.value = true;
    error.value = null;
    try {
      const { data } = await api.get('/events', { params });
      events.value = data.data;
      pagination.value = {
        page: data.page,
        limit: data.limit,
        total: data.total,
      };
    } catch (e: any) {
      error.value = e.response?.data?.detail || 'Error fetching events';
    } finally {
      loading.value = false;
    }
  };

  const createEvent = async (data: Partial<Event>) => {
    const { data: newEvent } = await api.post('/events', data);
    events.value.unshift(newEvent);
    return newEvent;
  };

  const updateEvent = async (id: string, data: Partial<Event>) => {
    const { data: updated } = await api.put(`/events/${id}`, data);
    const index = events.value.findIndex(item => item.id === id);
    if (index !== -1) {
      events.value[index] = updated;
    }
    return updated;
  };

  const deleteEvent = async (id: string) => {
    await api.delete(`/events/${id}`);
    events.value = events.value.filter(item => item.id !== id);
  };

  return {
    events,
    loading,
    error,
    pagination,
    fetchEvents,
    createEvent,
    updateEvent,
    deleteEvent,
  };
});
```

