```python
from fastapi import APIRouter, Depends, HTTPException, Query
from sqlalchemy.orm import Session
from typing import Optional
from app.api.deps import get_db, get_current_user
from app.models.workout import Workout
from app.models.user import User
from app.schemas.workout import (
    WorkoutCreate,
    WorkoutUpdate,
    WorkoutResponse,
    WorkoutListResponse,
)

router = APIRouter()

@router.get("/", response_model=WorkoutListResponse)
async def list_workouts(
    page: int = Query(1, ge=1),
    limit: int = Query(10, ge=1, le=100),
    search: Optional[str] = None,
    status: Optional[str] = None,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    query = db.query(Workout).filter(Workout.user_id == current_user.id)

    if search:
        query = query.filter(Workout.title.ilike(f"%{search}%"))
    if status:
        query = query.filter(Workout.status == status)

    total = query.count()
    workouts = query.offset((page - 1) * limit).limit(limit).all()

    return WorkoutListResponse(
        data=workouts,
        total=total,
        page=page,
        limit=limit
    )

@router.get("/{id}", response_model=WorkoutResponse)
async def get_workout(
    id: str,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    workout = db.query(Workout).filter(
        Workout.id == id,
        Workout.user_id == current_user.id
    ).first()

    if not workout:
        raise HTTPException(status_code=404, detail="Workout not found")

    return workout

@router.post("/", response_model=WorkoutResponse, status_code=201)
async def create_workout(
    data: WorkoutCreate,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    workout = Workout(**data.model_dump(), user_id=current_user.id)
    db.add(workout)
    db.commit()
    db.refresh(workout)
    return workout

@router.put("/{id}", response_model=WorkoutResponse)
async def update_workout(
    id: str,
    data: WorkoutUpdate,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    workout = db.query(Workout).filter(
        Workout.id == id,
        Workout.user_id == current_user.id
    ).first()

    if not workout:
        raise HTTPException(status_code=404, detail="Workout not found")

    for key, value in data.model_dump(exclude_unset=True).items():
        setattr(workout, key, value)

    db.commit()
    db.refresh(workout)
    return workout

@router.delete("/{id}", status_code=204)
async def delete_workout(
    id: str,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    workout = db.query(Workout).filter(
        Workout.id == id,
        Workout.user_id == current_user.id
    ).first()

    if not workout:
        raise HTTPException(status_code=404, detail="Workout not found")

    db.delete(workout)
    db.commit()
