import { defineStore } from 'pinia';
import { ref, computed } from 'vue';
import api from '@/services/api';

interface Workout {
  id: string;
  title: string;
  description: string | null;
  status: string;
  createdAt: string;
}

export const useWorkoutStore = defineStore('workouts', () => {
  const workouts = ref<Workout[]>([]);
  const loading = ref(false);
  const error = ref<string | null>(null);
  const pagination = ref({ page: 1, limit: 10, total: 0 });

  const fetchWorkouts = async (params?: Record<string, any>) => {
    loading.value = true;
    error.value = null;
    try {
      const { data } = await api.get('/workouts', { params });
      workouts.value = data.data;
      pagination.value = {
        page: data.page,
        limit: data.limit,
        total: data.total,
      };
    } catch (e: any) {
      error.value = e.response?.data?.detail || 'Error fetching workouts';
    } finally {
      loading.value = false;
    }
  };

  const createWorkout = async (data: Partial<Workout>) => {
    const { data: newWorkout } = await api.post('/workouts', data);
    workouts.value.unshift(newWorkout);
    return newWorkout;
  };

  const updateWorkout = async (id: string, data: Partial<Workout>) => {
    const { data: updated } = await api.put(`/workouts/${id}`, data);
    const index = workouts.value.findIndex(item => item.id === id);
    if (index !== -1) {
      workouts.value[index] = updated;
    }
    return updated;
  };

  const deleteWorkout = async (id: string) => {
    await api.delete(`/workouts/${id}`);
    workouts.value = workouts.value.filter(item => item.id !== id);
  };

  return {
    workouts,
    loading,
    error,
    pagination,
    fetchWorkouts,
    createWorkout,
    updateWorkout,
    deleteWorkout,
  };
});
