package com.itemapp.service;

import com.itemapp.dto.ItemDto;
import com.itemapp.exception.ResourceNotFoundException;
import com.itemapp.model.Item;
import com.itemapp.model.User;
import com.itemapp.repository.ItemRepository;
import com.itemapp.repository.UserRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
public class ItemService {

    private final ItemRepository itemRepository;
    private final UserRepository userRepository;

    public Page<Item> findAll(String username, String search, Pageable pageable) {
        User user = getUserByUsername(username);
        if (search != null && !search.isEmpty()) {
            return itemRepository.findByUserAndTitleContainingIgnoreCase(user, search, pageable);
        }
        return itemRepository.findByUser(user, pageable);
    }

    public Item findById(Long id, String username) {
        User user = getUserByUsername(username);
        return itemRepository.findByIdAndUser(id, user)
                .orElseThrow(() -> new ResourceNotFoundException("Item not found"));
    }

    @Transactional
    public Item create(ItemDto dto, String username) {
        User user = getUserByUsername(username);
        Item item = new Item();
        item.setTitle(dto.getTitle());
        item.setDescription(dto.getDescription());
        item.setStatus(dto.getStatus() != null ? dto.getStatus() : "active");
        item.setUser(user);
        return itemRepository.save(item);
    }

    @Transactional
    public Item update(Long id, ItemDto dto, String username) {
        Item item = findById(id, username);
        if (dto.getTitle() != null) item.setTitle(dto.getTitle());
        if (dto.getDescription() != null) item.setDescription(dto.getDescription());
        if (dto.getStatus() != null) item.setStatus(dto.getStatus());
        return itemRepository.save(item);
    }

    @Transactional
    public void delete(Long id, String username) {
        Item item = findById(id, username);
        itemRepository.delete(item);
    }

    private User getUserByUsername(String username) {
        return userRepository.findByEmail(username)
                .orElseThrow(() -> new ResourceNotFoundException("User not found"));
    }
}
