## Backend - src/properties/properties.service.ts

```typescript
import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository, Like } from 'typeorm';
import { Property } from './entities/property.entity';
import { CreatePropertyDto } from './dto/create-property.dto';
import { UpdatePropertyDto } from './dto/update-property.dto';

@Injectable()
export class PropertysService {
  constructor(
    @InjectRepository(Property)
    private propertiesRepository: Repository<Property>,
  ) {}

  async findAll(userId: string, options: { page: number; limit: number; search?: string }) {
    const { page, limit, search } = options;

    const where: any = { userId };
    if (search) {
      where.title = Like(`%${search}%`);
    }

    const [data, total] = await this.propertiesRepository.findAndCount({
      where,
      order: { createdAt: 'DESC' },
      skip: (page - 1) * limit,
      take: limit,
    });

    return {
      data,
      total,
      page,
      limit,
      pages: Math.ceil(total / limit),
    };
  }

  async findOne(id: string, userId: string) {
    const property = await this.propertiesRepository.findOne({
      where: { id, userId },
    });

    if (!property) {
      throw new NotFoundException('Property not found');
    }

    return property;
  }

  async create(createPropertyDto: CreatePropertyDto, userId: string) {
    const property = this.propertiesRepository.create({
      ...createPropertyDto,
      userId,
    });
    return this.propertiesRepository.save(property);
  }

  async update(id: string, updatePropertyDto: UpdatePropertyDto, userId: string) {
    const property = await this.findOne(id, userId);
    Object.assign(property, updatePropertyDto);
    return this.propertiesRepository.save(property);
  }

  async remove(id: string, userId: string) {
    const property = await this.findOne(id, userId);
    await this.propertiesRepository.remove(property);
    return { deleted: true };
  }
}
