import { useState, useEffect, useCallback } from 'react';
import api from '../services/api';

export function useTickets() {
  const [tickets, setTickets] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [pagination, setPagination] = useState({
    page: 1,
    limit: 10,
    total: 0
  });

  const fetchTickets = useCallback(async (params = {}) => {
    try {
      setLoading(true);
      const { data } = await api.get('/tickets', { params });
      setTickets(data.data);
      setPagination(data.pagination);
    } catch (err) {
      setError(err.response?.data?.message || 'Error fetching tickets');
    } finally {
      setLoading(false);
    }
  }, []);

  const createTicket = async (ticketData) => {
    const { data } = await api.post('/tickets', ticketData);
    setTickets(prev => [data.data, ...prev]);
    return data.data;
  };

  const updateTicket = async (id, ticketData) => {
    const { data } = await api.put(`/tickets/${id}`, ticketData);
    setTickets(prev => prev.map(item =>
      item._id === id ? data.data : item
    ));
    return data.data;
  };

  const deleteTicket = async (id) => {
    await api.delete(`/tickets/${id}`);
    setTickets(prev => prev.filter(item => item._id !== id));
  };

  useEffect(() => {
    fetchTickets();
  }, [fetchTickets]);

  return {
    tickets,
    loading,
    error,
    pagination,
    fetchTickets,
    createTicket,
    updateTicket,
    deleteTicket
  };
}
