```java
package com.propertyapp.controller;

import com.propertyapp.dto.PropertyDto;
import com.propertyapp.model.Property;
import com.propertyapp.service.PropertyService;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.web.bind.annotation.*;

import jakarta.validation.Valid;

@RestController
@RequestMapping("/api/properties")
@RequiredArgsConstructor
public class PropertyController {

    private final PropertyService propertyService;

    @GetMapping
    public ResponseEntity<Page<Property>> getAll(
            @AuthenticationPrincipal UserDetails userDetails,
            Pageable pageable,
            @RequestParam(required = false) String search
    ) {
        Page<Property> properties = propertyService.findAll(userDetails.getUsername(), search, pageable);
        return ResponseEntity.ok(properties);
    }

    @GetMapping("/{id}")
    public ResponseEntity<Property> getOne(
            @AuthenticationPrincipal UserDetails userDetails,
            @PathVariable Long id
    ) {
        Property property = propertyService.findById(id, userDetails.getUsername());
        return ResponseEntity.ok(property);
    }

    @PostMapping
    public ResponseEntity<Property> create(
            @AuthenticationPrincipal UserDetails userDetails,
            @Valid @RequestBody PropertyDto dto
    ) {
        Property property = propertyService.create(dto, userDetails.getUsername());
        return ResponseEntity.status(HttpStatus.CREATED).body(property);
    }

    @PutMapping("/{id}")
    public ResponseEntity<Property> update(
            @AuthenticationPrincipal UserDetails userDetails,
            @PathVariable Long id,
            @Valid @RequestBody PropertyDto dto
    ) {
        Property property = propertyService.update(id, dto, userDetails.getUsername());
        return ResponseEntity.ok(property);
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<Void> delete(
            @AuthenticationPrincipal UserDetails userDetails,
            @PathVariable Long id
    ) {
        propertyService.delete(id, userDetails.getUsername());
        return ResponseEntity.noContent().build();
    }
}
