## Backend - PropertyService.java

```java
package com.propertyapp.service;

import com.propertyapp.dto.PropertyDto;
import com.propertyapp.exception.ResourceNotFoundException;
import com.propertyapp.model.Property;
import com.propertyapp.model.User;
import com.propertyapp.repository.PropertyRepository;
import com.propertyapp.repository.UserRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
public class PropertyService {

    private final PropertyRepository propertyRepository;
    private final UserRepository userRepository;

    public Page<Property> findAll(String username, String search, Pageable pageable) {
        User user = getUserByUsername(username);
        if (search != null && !search.isEmpty()) {
            return propertyRepository.findByUserAndTitleContainingIgnoreCase(user, search, pageable);
        }
        return propertyRepository.findByUser(user, pageable);
    }

    public Property findById(Long id, String username) {
        User user = getUserByUsername(username);
        return propertyRepository.findByIdAndUser(id, user)
                .orElseThrow(() -> new ResourceNotFoundException("Property not found"));
    }

    @Transactional
    public Property create(PropertyDto dto, String username) {
        User user = getUserByUsername(username);
        Property property = new Property();
        property.setTitle(dto.getTitle());
        property.setDescription(dto.getDescription());
        property.setStatus(dto.getStatus() != null ? dto.getStatus() : "active");
        property.setUser(user);
        return propertyRepository.save(property);
    }

    @Transactional
    public Property update(Long id, PropertyDto dto, String username) {
        Property property = findById(id, username);
        if (dto.getTitle() != null) property.setTitle(dto.getTitle());
        if (dto.getDescription() != null) property.setDescription(dto.getDescription());
        if (dto.getStatus() != null) property.setStatus(dto.getStatus());
        return propertyRepository.save(property);
    }

    @Transactional
    public void delete(Long id, String username) {
        Property property = findById(id, username);
        propertyRepository.delete(property);
    }

    private User getUserByUsername(String username) {
        return userRepository.findByEmail(username)
                .orElseThrow(() -> new ResourceNotFoundException("User not found"));
    }
}
