```javascript
import { useState, useEffect, useCallback } from 'react';
import api from '../services/api';

export function useRecipes() {
  const [recipes, setRecipes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [pagination, setPagination] = useState({
    page: 1,
    limit: 10,
    total: 0
  });

  const fetchRecipes = useCallback(async (params = {}) => {
    try {
      setLoading(true);
      const { data } = await api.get('/recipes', { params });
      setRecipes(data.data);
      setPagination(data.pagination);
    } catch (err) {
      setError(err.response?.data?.message || 'Error fetching recipes');
    } finally {
      setLoading(false);
    }
  }, []);

  const createRecipe = async (recipeData) => {
    const { data } = await api.post('/recipes', recipeData);
    setRecipes(prev => [data.data, ...prev]);
    return data.data;
  };

  const updateRecipe = async (id, recipeData) => {
    const { data } = await api.put(`/recipes/${id}`, recipeData);
    setRecipes(prev => prev.map(item =>
      item._id === id ? data.data : item
    ));
    return data.data;
  };

  const deleteRecipe = async (id) => {
    await api.delete(`/recipes/${id}`);
    setRecipes(prev => prev.filter(item => item._id !== id));
  };

  useEffect(() => {
    fetchRecipes();
  }, [fetchRecipes]);

  return {
    recipes,
    loading,
    error,
    pagination,
    fetchRecipes,
    createRecipe,
    updateRecipe,
    deleteRecipe
  };
}
```

## Frontend - client/src/context/AuthContext.jsx

```jsx
import { createContext, useState, useEffect } from 'react';
import api from '../services/api';

export const AuthContext = createContext();

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const token = localStorage.getItem('token');
    if (token) {
      loadUser();
    } else {
      setLoading(false);
    }
  }, []);

  const loadUser = async () => {
    try {
      const { data } = await api.get('/auth/me');
      setUser(data.data);
    } catch (error) {
      localStorage.removeItem('token');
    } finally {
      setLoading(false);
    }
  };

  const login = async (email, password) => {
    const { data } = await api.post('/auth/login', { email, password });
    localStorage.setItem('token', data.token);
    setUser(data.user);
    return data;
  };

  const register = async (name, email, password) => {
    const { data } = await api.post('/auth/register', { name, email, password });
    localStorage.setItem('token', data.token);
    setUser(data.user);
    return data;
  };

  const logout = () => {
    localStorage.removeItem('token');
    setUser(null);
  };

  return (
    <AuthContext.Provider value={{ user, loading, login, register, logout }}>
      {children}
    </AuthContext.Provider>
  );
}
