## Frontend - src/stores/projects.ts

```typescript
import { defineStore } from 'pinia';
import { ref, computed } from 'vue';
import api from '@/services/api';

interface Project {
  id: string;
  title: string;
  description: string | null;
  status: string;
  createdAt: string;
}

export const useProjectStore = defineStore('projects', () => {
  const projects = ref<Project[]>([]);
  const loading = ref(false);
  const error = ref<string | null>(null);
  const pagination = ref({ page: 1, limit: 10, total: 0 });

  const fetchProjects = async (params?: Record<string, any>) => {
    loading.value = true;
    error.value = null;
    try {
      const { data } = await api.get('/projects', { params });
      projects.value = data.data;
      pagination.value = {
        page: data.page,
        limit: data.limit,
        total: data.total,
      };
    } catch (e: any) {
      error.value = e.response?.data?.detail || 'Error fetching projects';
    } finally {
      loading.value = false;
    }
  };

  const createProject = async (data: Partial<Project>) => {
    const { data: newProject } = await api.post('/projects', data);
    projects.value.unshift(newProject);
    return newProject;
  };

  const updateProject = async (id: string, data: Partial<Project>) => {
    const { data: updated } = await api.put(`/projects/${id}`, data);
    const index = projects.value.findIndex(item => item.id === id);
    if (index !== -1) {
      projects.value[index] = updated;
    }
    return updated;
  };

  const deleteProject = async (id: string) => {
    await api.delete(`/projects/${id}`);
    projects.value = projects.value.filter(item => item.id !== id);
  };

  return {
    projects,
    loading,
    error,
    pagination,
    fetchProjects,
    createProject,
    updateProject,
    deleteProject,
  };
});
```

