```javascript
import { useState, useEffect, useCallback } from 'react';
import api from '../services/api';

export function useCourses() {
  const [courses, setCourses] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [pagination, setPagination] = useState({
    page: 1,
    limit: 10,
    total: 0
  });

  const fetchCourses = useCallback(async (params = {}) => {
    try {
      setLoading(true);
      const { data } = await api.get('/courses', { params });
      setCourses(data.data);
      setPagination(data.pagination);
    } catch (err) {
      setError(err.response?.data?.message || 'Error fetching courses');
    } finally {
      setLoading(false);
    }
  }, []);

  const createCourse = async (courseData) => {
    const { data } = await api.post('/courses', courseData);
    setCourses(prev => [data.data, ...prev]);
    return data.data;
  };

  const updateCourse = async (id, courseData) => {
    const { data } = await api.put(`/courses/${id}`, courseData);
    setCourses(prev => prev.map(item =>
      item._id === id ? data.data : item
    ));
    return data.data;
  };

  const deleteCourse = async (id) => {
    await api.delete(`/courses/${id}`);
    setCourses(prev => prev.filter(item => item._id !== id));
  };

  useEffect(() => {
    fetchCourses();
  }, [fetchCourses]);

  return {
    courses,
    loading,
    error,
    pagination,
    fetchCourses,
    createCourse,
    updateCourse,
    deleteCourse
  };
