## Backend - src/jobs/jobs.service.ts

```typescript
import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository, Like } from 'typeorm';
import { Job } from './entities/job.entity';
import { CreateJobDto } from './dto/create-job.dto';
import { UpdateJobDto } from './dto/update-job.dto';

@Injectable()
export class JobsService {
  constructor(
    @InjectRepository(Job)
    private jobsRepository: Repository<Job>,
  ) {}

  async findAll(userId: string, options: { page: number; limit: number; search?: string }) {
    const { page, limit, search } = options;

    const where: any = { userId };
    if (search) {
      where.title = Like(`%${search}%`);
    }

    const [data, total] = await this.jobsRepository.findAndCount({
      where,
      order: { createdAt: 'DESC' },
      skip: (page - 1) * limit,
      take: limit,
    });

    return {
      data,
      total,
      page,
      limit,
      pages: Math.ceil(total / limit),
    };
  }

  async findOne(id: string, userId: string) {
    const job = await this.jobsRepository.findOne({
      where: { id, userId },
    });

    if (!job) {
      throw new NotFoundException('Job not found');
    }

    return job;
  }

  async create(createJobDto: CreateJobDto, userId: string) {
    const job = this.jobsRepository.create({
      ...createJobDto,
      userId,
    });
    return this.jobsRepository.save(job);
  }

  async update(id: string, updateJobDto: UpdateJobDto, userId: string) {
    const job = await this.findOne(id, userId);
    Object.assign(job, updateJobDto);
    return this.jobsRepository.save(job);
  }

  async remove(id: string, userId: string) {
    const job = await this.findOne(id, userId);
    await this.jobsRepository.remove(job);
    return { deleted: true };
  }
}
