## Backend - app/api/routes/properties.py

```python
from fastapi import APIRouter, Depends, HTTPException, Query
from sqlalchemy.orm import Session
from typing import Optional
from app.api.deps import get_db, get_current_user
from app.models.property import Property
from app.models.user import User
from app.schemas.property import (
    PropertyCreate,
    PropertyUpdate,
    PropertyResponse,
    PropertyListResponse,
)

router = APIRouter()

@router.get("/", response_model=PropertyListResponse)
async def list_properties(
    page: int = Query(1, ge=1),
    limit: int = Query(10, ge=1, le=100),
    search: Optional[str] = None,
    status: Optional[str] = None,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    query = db.query(Property).filter(Property.user_id == current_user.id)

    if search:
        query = query.filter(Property.title.ilike(f"%{search}%"))
    if status:
        query = query.filter(Property.status == status)

    total = query.count()
    properties = query.offset((page - 1) * limit).limit(limit).all()

    return PropertyListResponse(
        data=properties,
        total=total,
        page=page,
        limit=limit
    )

@router.get("/{id}", response_model=PropertyResponse)
async def get_property(
    id: str,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    property = db.query(Property).filter(
        Property.id == id,
        Property.user_id == current_user.id
    ).first()

    if not property:
        raise HTTPException(status_code=404, detail="Property not found")

    return property

@router.post("/", response_model=PropertyResponse, status_code=201)
async def create_property(
    data: PropertyCreate,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    property = Property(**data.model_dump(), user_id=current_user.id)
    db.add(property)
    db.commit()
    db.refresh(property)
    return property

@router.put("/{id}", response_model=PropertyResponse)
async def update_property(
    id: str,
    data: PropertyUpdate,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    property = db.query(Property).filter(
        Property.id == id,
        Property.user_id == current_user.id
    ).first()

    if not property:
        raise HTTPException(status_code=404, detail="Property not found")

    for key, value in data.model_dump(exclude_unset=True).items():
        setattr(property, key, value)

    db.commit()
    db.refresh(property)
    return property

@router.delete("/{id}", status_code=204)
async def delete_property(
    id: str,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    property = db.query(Property).filter(
        Property.id == id,
        Property.user_id == current_user.id
    ).first()

    if not property:
        raise HTTPException(status_code=404, detail="Property not found")

    db.delete(property)
    db.commit()
