## Frontend - src/stores/properties.ts

```typescript
import { defineStore } from 'pinia';
import { ref, computed } from 'vue';
import api from '@/services/api';

interface Property {
  id: string;
  title: string;
  description: string | null;
  status: string;
  createdAt: string;
}

export const usePropertyStore = defineStore('properties', () => {
  const properties = ref<Property[]>([]);
  const loading = ref(false);
  const error = ref<string | null>(null);
  const pagination = ref({ page: 1, limit: 10, total: 0 });

  const fetchPropertys = async (params?: Record<string, any>) => {
    loading.value = true;
    error.value = null;
    try {
      const { data } = await api.get('/properties', { params });
      properties.value = data.data;
      pagination.value = {
        page: data.page,
        limit: data.limit,
        total: data.total,
      };
    } catch (e: any) {
      error.value = e.response?.data?.detail || 'Error fetching properties';
    } finally {
      loading.value = false;
    }
  };

  const createProperty = async (data: Partial<Property>) => {
    const { data: newProperty } = await api.post('/properties', data);
    properties.value.unshift(newProperty);
    return newProperty;
  };

  const updateProperty = async (id: string, data: Partial<Property>) => {
    const { data: updated } = await api.put(`/properties/${id}`, data);
    const index = properties.value.findIndex(item => item.id === id);
    if (index !== -1) {
      properties.value[index] = updated;
    }
    return updated;
  };

  const deleteProperty = async (id: string) => {
    await api.delete(`/properties/${id}`);
    properties.value = properties.value.filter(item => item.id !== id);
  };

  return {
    properties,
    loading,
    error,
    pagination,
    fetchPropertys,
    createProperty,
    updateProperty,
    deleteProperty,
  };
});
