'use client';

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import TicketForm from './TicketForm';
import Card from './ui/Card';
import Button from './ui/Button';

interface Ticket {
  id: string;
  title: string;
  description: string | null;
  status: string;
  createdAt: Date;
}

export default function TicketList({ initialTickets }: { initialTickets: Ticket[] }) {
  const [tickets, setTickets] = useState(initialTickets);
  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState<Ticket | null>(null);
  const router = useRouter();

  const handleCreate = async (data: any) => {
    const res = await fetch('/api/tickets', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data),
    });

    if (res.ok) {
      const { data: newTicket } = await res.json();
      setTickets([newTicket, ...tickets]);
      setShowForm(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Are you sure?')) return;

    const res = await fetch(`/api/tickets/${id}`, { method: 'DELETE' });

    if (res.ok) {
      setTickets(tickets.filter(item => item.id !== id));
    }
  };

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold">My Tickets</h1>
        <Button onClick={() => setShowForm(true)}>
          Add Ticket
        </Button>
      </div>

      {showForm && (
        <div className="mb-6">
          <TicketForm
            onSubmit={handleCreate}
            onCancel={() => setShowForm(false)}
          />
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {tickets.map(ticket => (
          <Card key={ticket.id} className="p-4">
            <h3 className="font-semibold">{ticket.title}</h3>
            <p className="text-gray-600 text-sm">{ticket.description}</p>
            <div className="flex gap-2 mt-4">
              <Button size="sm" variant="outline" onClick={() => router.push(`/dashboard/tickets/${ticket.id}`)}>
                Edit
              </Button>
              <Button size="sm" variant="danger" onClick={() => handleDelete(ticket.id)}>
                Delete
              </Button>
            </div>
          </Card>
        ))}
      </div>
    </div>
  );
}
