import com.eventapp.model.User;
import com.eventapp.repository.EventRepository;
import com.eventapp.repository.UserRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
public class EventService {

    private final EventRepository eventRepository;
    private final UserRepository userRepository;

    public Page<Event> findAll(String username, String search, Pageable pageable) {
        User user = getUserByUsername(username);
        if (search != null && !search.isEmpty()) {
            return eventRepository.findByUserAndTitleContainingIgnoreCase(user, search, pageable);
        }
        return eventRepository.findByUser(user, pageable);
    }

    public Event findById(Long id, String username) {
        User user = getUserByUsername(username);
        return eventRepository.findByIdAndUser(id, user)
                .orElseThrow(() -> new ResourceNotFoundException("Event not found"));
    }

    @Transactional
    public Event create(EventDto dto, String username) {
        User user = getUserByUsername(username);
        Event event = new Event();
        event.setTitle(dto.getTitle());
        event.setDescription(dto.getDescription());
        event.setStatus(dto.getStatus() != null ? dto.getStatus() : "active");
        event.setUser(user);
        return eventRepository.save(event);
    }

    @Transactional
    public Event update(Long id, EventDto dto, String username) {
        Event event = findById(id, username);
        if (dto.getTitle() != null) event.setTitle(dto.getTitle());
        if (dto.getDescription() != null) event.setDescription(dto.getDescription());
        if (dto.getStatus() != null) event.setStatus(dto.getStatus());
        return eventRepository.save(event);
    }

    @Transactional
    public void delete(Long id, String username) {
        Event event = findById(id, username);
        eventRepository.delete(event);
    }

    private User getUserByUsername(String username) {
        return userRepository.findByEmail(username)
                .orElseThrow(() -> new ResourceNotFoundException("User not found"));
    }
}
