## Backend - app/api/routes/courses.py

```python
from fastapi import APIRouter, Depends, HTTPException, Query
from sqlalchemy.orm import Session
from typing import Optional
from app.api.deps import get_db, get_current_user
from app.models.course import Course
from app.models.user import User
from app.schemas.course import (
    CourseCreate,
    CourseUpdate,
    CourseResponse,
    CourseListResponse,
)

router = APIRouter()

@router.get("/", response_model=CourseListResponse)
async def list_courses(
    page: int = Query(1, ge=1),
    limit: int = Query(10, ge=1, le=100),
    search: Optional[str] = None,
    status: Optional[str] = None,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    query = db.query(Course).filter(Course.user_id == current_user.id)

    if search:
        query = query.filter(Course.title.ilike(f"%{search}%"))
    if status:
        query = query.filter(Course.status == status)

    total = query.count()
    courses = query.offset((page - 1) * limit).limit(limit).all()

    return CourseListResponse(
        data=courses,
        total=total,
        page=page,
        limit=limit
    )

@router.get("/{id}", response_model=CourseResponse)
async def get_course(
    id: str,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    course = db.query(Course).filter(
        Course.id == id,
        Course.user_id == current_user.id
    ).first()

    if not course:
        raise HTTPException(status_code=404, detail="Course not found")

    return course

@router.post("/", response_model=CourseResponse, status_code=201)
async def create_course(
    data: CourseCreate,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    course = Course(**data.model_dump(), user_id=current_user.id)
    db.add(course)
    db.commit()
    db.refresh(course)
    return course

@router.put("/{id}", response_model=CourseResponse)
async def update_course(
    id: str,
    data: CourseUpdate,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    course = db.query(Course).filter(
        Course.id == id,
        Course.user_id == current_user.id
    ).first()

    if not course:
        raise HTTPException(status_code=404, detail="Course not found")

    for key, value in data.model_dump(exclude_unset=True).items():
        setattr(course, key, value)

    db.commit()
    db.refresh(course)
    return course

@router.delete("/{id}", status_code=204)
async def delete_course(
    id: str,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    course = db.query(Course).filter(
        Course.id == id,
        Course.user_id == current_user.id
    ).first()

    if not course:
        raise HTTPException(status_code=404, detail="Course not found")

    db.delete(course)
    db.commit()
```

## Frontend - src/stores/courses.ts

```typescript
import { defineStore } from 'pinia';
import { ref, computed } from 'vue';
import api from '@/services/api';

interface Course {
  id: string;
  title: string;
  description: string | null;
  status: string;
  createdAt: string;
}

export const useCourseStore = defineStore('courses', () => {
  const courses = ref<Course[]>([]);
  const loading = ref(false);
  const error = ref<string | null>(null);
  const pagination = ref({ page: 1, limit: 10, total: 0 });

  const fetchCourses = async (params?: Record<string, any>) => {
    loading.value = true;
    error.value = null;
    try {
      const { data } = await api.get('/courses', { params });
      courses.value = data.data;
      pagination.value = {
        page: data.page,
        limit: data.limit,
        total: data.total,
      };
    } catch (e: any) {
      error.value = e.response?.data?.detail || 'Error fetching courses';
    } finally {
      loading.value = false;
    }
  };

  const createCourse = async (data: Partial<Course>) => {
    const { data: newCourse } = await api.post('/courses', data);
    courses.value.unshift(newCourse);
    return newCourse;
  };

  const updateCourse = async (id: string, data: Partial<Course>) => {
    const { data: updated } = await api.put(`/courses/${id}`, data);
    const index = courses.value.findIndex(item => item.id === id);
    if (index !== -1) {
      courses.value[index] = updated;
    }
    return updated;
  };

  const deleteCourse = async (id: string) => {
    await api.delete(`/courses/${id}`);
    courses.value = courses.value.filter(item => item.id !== id);
  };

  return {
    courses,
    loading,
    error,
    pagination,
    fetchCourses,
    createCourse,
    updateCourse,
    deleteCourse,
  };
});
```

