## Backend - app/api/routes/jobs.py

```python
from fastapi import APIRouter, Depends, HTTPException, Query
from sqlalchemy.orm import Session
from typing import Optional
from app.api.deps import get_db, get_current_user
from app.models.job import Job
from app.models.user import User
from app.schemas.job import (
    JobCreate,
    JobUpdate,
    JobResponse,
    JobListResponse,
)

router = APIRouter()

@router.get("/", response_model=JobListResponse)
async def list_jobs(
    page: int = Query(1, ge=1),
    limit: int = Query(10, ge=1, le=100),
    search: Optional[str] = None,
    status: Optional[str] = None,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    query = db.query(Job).filter(Job.user_id == current_user.id)

    if search:
        query = query.filter(Job.title.ilike(f"%{search}%"))
    if status:
        query = query.filter(Job.status == status)

    total = query.count()
    jobs = query.offset((page - 1) * limit).limit(limit).all()

    return JobListResponse(
        data=jobs,
        total=total,
        page=page,
        limit=limit
    )

@router.get("/{id}", response_model=JobResponse)
async def get_job(
    id: str,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    job = db.query(Job).filter(
        Job.id == id,
        Job.user_id == current_user.id
    ).first()

    if not job:
        raise HTTPException(status_code=404, detail="Job not found")

    return job

@router.post("/", response_model=JobResponse, status_code=201)
async def create_job(
    data: JobCreate,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    job = Job(**data.model_dump(), user_id=current_user.id)
    db.add(job)
    db.commit()
    db.refresh(job)
    return job

@router.put("/{id}", response_model=JobResponse)
async def update_job(
    id: str,
    data: JobUpdate,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    job = db.query(Job).filter(
        Job.id == id,
        Job.user_id == current_user.id
    ).first()

    if not job:
        raise HTTPException(status_code=404, detail="Job not found")

    for key, value in data.model_dump(exclude_unset=True).items():
        setattr(job, key, value)

    db.commit()
    db.refresh(job)
    return job

@router.delete("/{id}", status_code=204)
async def delete_job(
    id: str,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    job = db.query(Job).filter(
        Job.id == id,
        Job.user_id == current_user.id
    ).first()

    if not job:
        raise HTTPException(status_code=404, detail="Job not found")

    db.delete(job)
    db.commit()
```

## Frontend - src/stores/jobs.ts

```typescript
import { defineStore } from 'pinia';
import { ref, computed } from 'vue';
import api from '@/services/api';

interface Job {
  id: string;
  title: string;
  description: string | null;
  status: string;
  createdAt: string;
}

export const useJobStore = defineStore('jobs', () => {
  const jobs = ref<Job[]>([]);
  const loading = ref(false);
  const error = ref<string | null>(null);
  const pagination = ref({ page: 1, limit: 10, total: 0 });

  const fetchJobs = async (params?: Record<string, any>) => {
    loading.value = true;
    error.value = null;
    try {
      const { data } = await api.get('/jobs', { params });
      jobs.value = data.data;
      pagination.value = {
        page: data.page,
        limit: data.limit,
        total: data.total,
      };
    } catch (e: any) {
      error.value = e.response?.data?.detail || 'Error fetching jobs';
    } finally {
      loading.value = false;
    }
  };

  const createJob = async (data: Partial<Job>) => {
    const { data: newJob } = await api.post('/jobs', data);
    jobs.value.unshift(newJob);
    return newJob;
  };

  const updateJob = async (id: string, data: Partial<Job>) => {
    const { data: updated } = await api.put(`/jobs/${id}`, data);
    const index = jobs.value.findIndex(item => item.id === id);
    if (index !== -1) {
      jobs.value[index] = updated;
    }
    return updated;
  };

  const deleteJob = async (id: string) => {
    await api.delete(`/jobs/${id}`);
    jobs.value = jobs.value.filter(item => item.id !== id);
  };

  return {
    jobs,
    loading,
    error,
    pagination,
    fetchJobs,
    createJob,
    updateJob,
    deleteJob,
  };
});
```

