'use client';

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import UserForm from './UserForm';
import Card from './ui/Card';
import Button from './ui/Button';

interface User {
  id: string;
  title: string;
  description: string | null;
  status: string;
  createdAt: Date;
}

export default function UserList({ initialUsers }: { initialUsers: User[] }) {
  const [users, setUsers] = useState(initialUsers);
  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState<User | null>(null);
  const router = useRouter();

  const handleCreate = async (data: any) => {
    const res = await fetch('/api/users', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data),
    });

    if (res.ok) {
      const { data: newUser } = await res.json();
      setUsers([newUser, ...users]);
      setShowForm(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Are you sure?')) return;

    const res = await fetch(`/api/users/${id}`, { method: 'DELETE' });

    if (res.ok) {
      setUsers(users.filter(item => item.id !== id));
    }
  };

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold">My Users</h1>
        <Button onClick={() => setShowForm(true)}>
          Add User
        </Button>
      </div>

      {showForm && (
        <div className="mb-6">
          <UserForm
            onSubmit={handleCreate}
            onCancel={() => setShowForm(false)}
          />
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {users.map(user => (
          <Card key={user.id} className="p-4">
            <h3 className="font-semibold">{user.title}</h3>
            <p className="text-gray-600 text-sm">{user.description}</p>
            <div className="flex gap-2 mt-4">
              <Button size="sm" variant="outline" onClick={() => router.push(`/dashboard/users/${user.id}`)}>
                Edit
              </Button>
              <Button size="sm" variant="danger" onClick={() => handleDelete(user.id)}>
                Delete
              </Button>
            </div>
          </Card>
        ))}
      </div>
    </div>
  );
}
