## Backend - src/bookings/bookings.service.ts

```typescript
import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository, Like } from 'typeorm';
import { Booking } from './entities/booking.entity';
import { CreateBookingDto } from './dto/create-booking.dto';
import { UpdateBookingDto } from './dto/update-booking.dto';

@Injectable()
export class BookingsService {
  constructor(
    @InjectRepository(Booking)
    private bookingsRepository: Repository<Booking>,
  ) {}

  async findAll(userId: string, options: { page: number; limit: number; search?: string }) {
    const { page, limit, search } = options;

    const where: any = { userId };
    if (search) {
      where.title = Like(`%${search}%`);
    }

    const [data, total] = await this.bookingsRepository.findAndCount({
      where,
      order: { createdAt: 'DESC' },
      skip: (page - 1) * limit,
      take: limit,
    });

    return {
      data,
      total,
      page,
      limit,
      pages: Math.ceil(total / limit),
    };
  }

  async findOne(id: string, userId: string) {
    const booking = await this.bookingsRepository.findOne({
      where: { id, userId },
    });

    if (!booking) {
      throw new NotFoundException('Booking not found');
    }

    return booking;
  }

  async create(createBookingDto: CreateBookingDto, userId: string) {
    const booking = this.bookingsRepository.create({
      ...createBookingDto,
      userId,
    });
    return this.bookingsRepository.save(booking);
  }

  async update(id: string, updateBookingDto: UpdateBookingDto, userId: string) {
    const booking = await this.findOne(id, userId);
    Object.assign(booking, updateBookingDto);
    return this.bookingsRepository.save(booking);
  }

  async remove(id: string, userId: string) {
    const booking = await this.findOne(id, userId);
    await this.bookingsRepository.remove(booking);
    return { deleted: true };
  }
}
