```typescript
import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository, Like } from 'typeorm';
import { Invoice } from './entities/invoice.entity';
import { CreateInvoiceDto } from './dto/create-invoice.dto';
import { UpdateInvoiceDto } from './dto/update-invoice.dto';

@Injectable()
export class InvoicesService {
  constructor(
    @InjectRepository(Invoice)
    private invoicesRepository: Repository<Invoice>,
  ) {}

  async findAll(userId: string, options: { page: number; limit: number; search?: string }) {
    const { page, limit, search } = options;

    const where: any = { userId };
    if (search) {
      where.title = Like(`%${search}%`);
    }

    const [data, total] = await this.invoicesRepository.findAndCount({
      where,
      order: { createdAt: 'DESC' },
      skip: (page - 1) * limit,
      take: limit,
    });

    return {
      data,
      total,
      page,
      limit,
      pages: Math.ceil(total / limit),
    };
  }

  async findOne(id: string, userId: string) {
    const invoice = await this.invoicesRepository.findOne({
      where: { id, userId },
    });

    if (!invoice) {
      throw new NotFoundException('Invoice not found');
    }

    return invoice;
  }

  async create(createInvoiceDto: CreateInvoiceDto, userId: string) {
    const invoice = this.invoicesRepository.create({
      ...createInvoiceDto,
      userId,
    });
    return this.invoicesRepository.save(invoice);
  }

  async update(id: string, updateInvoiceDto: UpdateInvoiceDto, userId: string) {
    const invoice = await this.findOne(id, userId);
    Object.assign(invoice, updateInvoiceDto);
    return this.invoicesRepository.save(invoice);
  }

  async remove(id: string, userId: string) {
    const invoice = await this.findOne(id, userId);
    await this.invoicesRepository.remove(invoice);
    return { deleted: true };
  }
}
