package com.bookingapp.controller;

import com.bookingapp.dto.BookingDto;
import com.bookingapp.model.Booking;
import com.bookingapp.service.BookingService;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.web.bind.annotation.*;

import jakarta.validation.Valid;

@RestController
@RequestMapping("/api/bookings")
@RequiredArgsConstructor
public class BookingController {

    private final BookingService bookingService;

    @GetMapping
    public ResponseEntity<Page<Booking>> getAll(
            @AuthenticationPrincipal UserDetails userDetails,
            Pageable pageable,
            @RequestParam(required = false) String search
    ) {
        Page<Booking> bookings = bookingService.findAll(userDetails.getUsername(), search, pageable);
        return ResponseEntity.ok(bookings);
    }

    @GetMapping("/{id}")
    public ResponseEntity<Booking> getOne(
            @AuthenticationPrincipal UserDetails userDetails,
            @PathVariable Long id
    ) {
        Booking booking = bookingService.findById(id, userDetails.getUsername());
        return ResponseEntity.ok(booking);
    }

    @PostMapping
    public ResponseEntity<Booking> create(
            @AuthenticationPrincipal UserDetails userDetails,
            @Valid @RequestBody BookingDto dto
    ) {
        Booking booking = bookingService.create(dto, userDetails.getUsername());
        return ResponseEntity.status(HttpStatus.CREATED).body(booking);
    }

    @PutMapping("/{id}")
    public ResponseEntity<Booking> update(
            @AuthenticationPrincipal UserDetails userDetails,
            @PathVariable Long id,
            @Valid @RequestBody BookingDto dto
    ) {
        Booking booking = bookingService.update(id, dto, userDetails.getUsername());
        return ResponseEntity.ok(booking);
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<Void> delete(
            @AuthenticationPrincipal UserDetails userDetails,
            @PathVariable Long id
    ) {
        bookingService.delete(id, userDetails.getUsername());
        return ResponseEntity.noContent().build();
    }
}
