```java
package com.bookingapp.service;

import com.bookingapp.dto.BookingDto;
import com.bookingapp.exception.ResourceNotFoundException;
import com.bookingapp.model.Booking;
import com.bookingapp.model.User;
import com.bookingapp.repository.BookingRepository;
import com.bookingapp.repository.UserRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
public class BookingService {

    private final BookingRepository bookingRepository;
    private final UserRepository userRepository;

    public Page<Booking> findAll(String username, String search, Pageable pageable) {
        User user = getUserByUsername(username);
        if (search != null && !search.isEmpty()) {
            return bookingRepository.findByUserAndTitleContainingIgnoreCase(user, search, pageable);
        }
        return bookingRepository.findByUser(user, pageable);
    }

    public Booking findById(Long id, String username) {
        User user = getUserByUsername(username);
        return bookingRepository.findByIdAndUser(id, user)
                .orElseThrow(() -> new ResourceNotFoundException("Booking not found"));
    }

    @Transactional
    public Booking create(BookingDto dto, String username) {
        User user = getUserByUsername(username);
        Booking booking = new Booking();
        booking.setTitle(dto.getTitle());
        booking.setDescription(dto.getDescription());
        booking.setStatus(dto.getStatus() != null ? dto.getStatus() : "active");
        booking.setUser(user);
        return bookingRepository.save(booking);
    }

    @Transactional
    public Booking update(Long id, BookingDto dto, String username) {
        Booking booking = findById(id, username);
        if (dto.getTitle() != null) booking.setTitle(dto.getTitle());
        if (dto.getDescription() != null) booking.setDescription(dto.getDescription());
        if (dto.getStatus() != null) booking.setStatus(dto.getStatus());
        return bookingRepository.save(booking);
    }

    @Transactional
    public void delete(Long id, String username) {
        Booking booking = findById(id, username);
        bookingRepository.delete(booking);
    }

    private User getUserByUsername(String username) {
        return userRepository.findByEmail(username)
                .orElseThrow(() -> new ResourceNotFoundException("User not found"));
    }
}
